# Generated by manage.py generate_test_cases.
"""Exercise reusable booking configuration and multiple destination calendars."""

from django.core.exceptions import ValidationError

from bloomerp.models.communication.calendar import CalendarBooking
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import CalendarFixtures


class TestCalendarBookingModel(CalendarFixtures, BloomerpModelTestCase):
    model = CalendarBooking

    def get_test_scenarios(self) -> list[ModelScenario[CalendarBooking]]:
        """Cover destinations without a host, token uniqueness, and availability inputs."""
        scenarios = [
            ModelScenario(
                name="Destinations do not infer a host or organizer",
                preparation=self.prepare,
                create_args=self.booking_args,
                post_create=self.set_destinations,
                create_validators=self.has_destinations,
            )
        ]
        scenarios.extend(
            [
                ModelScenario(
                    name="Zero duration",
                    preparation=self.prepare,
                    create_args=self.zero_duration,
                    expected_exceptions=[
                        ExpectedModelException("create", ValidationError)
                    ],
                ),
                ModelScenario(
                    name="Invalid availability timezone",
                    preparation=self.prepare,
                    create_args=self.invalid_timezone,
                    expected_exceptions=[
                        ExpectedModelException("create", ValidationError)
                    ],
                ),
            ]
        )
        return scenarios

    def set_destinations(self, booking: CalendarBooking) -> None:
        """Assign all destination calendars instead of choosing one from a pool."""
        booking.target_inboxes.add(self.inbox, self.team_inbox)

    def has_destinations(self, booking: CalendarBooking) -> bool:
        """Verify retained description, independent random tokens, and all destinations."""
        return (
            booking.target_inboxes.count() == 2
            and booking.organizing_inbox_id == self.inbox.pk
            and booking.public_token != self.booking.public_token
            and booking.description == "Discuss your project"
        )

    def zero_duration(self) -> dict[str, object]:
        """Attempt a booking duration that cannot describe a meeting."""
        return self.booking_args(meeting_duration_minutes=0)

    def invalid_timezone(self) -> dict[str, object]:
        """Attempt an unresolved timezone instead of guessing its offset."""
        return self.booking_args(timezone="Not/AZone")
